import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def find_solutions(max_a, max_b):
    solutions = []
    for a in range(1, max_a + 1):
        for b in range(1, max_b + 1):
            # check if a^2 - 4a/b is a square of a rational
            # a^2 - 4a/b = q^2
            # (a^2 b - 4a) / b = q^2
            # This means b * (a^2 b - 4a) must be a square of an integer
            val = b * (a**2 * b - 4 * a)
            if val > 0 and is_square(val):
                solutions.append((a, b))
    return solutions

print(find_solutions(100, 100))
